export default function ContactForm() {
  async function submitContactMessage(formData: FormData) {
    'use server'

    const name = formData.get('name')
    const email = formData.get('email')
    const message = formData.get('message')

    if (
      typeof name !== 'string' || !name.trim() ||
      typeof email !== 'string' || !email.trim() ||
      typeof message !== 'string' || !message.trim()
    ) {
      throw new Error('Name, email, and message are required')
    }

    // Simulate sending the contact message (no delivery service is configured).
    console.log('Contact message:', { name: name.trim(), email: email.trim(), message: message.trim() })
  }

  return (
    <div>
      <h2>Contact Us</h2>
      <form action={submitContactMessage}>
        <label htmlFor="contact-name">Name</label>
        <input id="contact-name" name="name" required />

        <label htmlFor="contact-email">Email</label>
        <input id="contact-email" name="email" type="email" required />

        <label htmlFor="contact-message">Message</label>
        <textarea id="contact-message" name="message" required />

        <button type="submit">Send Message</button>
      </form>
    </div>
  )
}

